<script setup lang="ts">
import {computed,ref} from 'vue';import {useRestaurant} from '../store';import OrderCard from '../components/OrderCard.vue';import {labels,type Status} from '../domain';
const s=useRestaurant(),includeDone=ref(false);const columns:Status[]=['Pending','Preparing','Ready'];
const orders=computed(()=>s.state.orders.filter(o=>s.role!=='Waiter'||s.state.sessions.find(x=>x.id===o.sessionId)?.waiter===s.waiter));
function table(id:string){const session=s.state.sessions.find(x=>x.id===id);return s.state.tables.find(t=>t.id===session?.tableId)?.code;}
</script><template><div class="page-heading"><div><p class="eyebrow">DE LA COCINA A LA MESA</p><h1>Servicio en cocina</h1><p class="muted">Instrucciones claras. Pedidos en el momento justo.</p></div><label class="checkbox"><input type="checkbox" v-model="includeDone"/> Ver historial</label></div><p v-if="!s.canCook" class="alert">Vista de consulta. Cambiá al rol Cocina para preparar pedidos.</p><div class="kanban"><section v-for="status in columns" class="kanban-column"><h2><i :class="status"></i>{{labels[status]}} <span>{{orders.filter(o=>o.status===status).length}}</span></h2><div v-for="o in orders.filter(o=>o.status===status)" :key="o.id"><p class="table-tag">MESA {{table(o.sessionId)}}</p><OrderCard :order="o"/></div><div v-if="!orders.some(o=>o.status===status)" class="empty"><span class="empty-symbol">✓</span><p>No hay pedidos aquí</p></div></section></div><section v-if="includeDone" class="history"><h2>Pedidos terminados</h2><OrderCard v-for="o in orders.filter(o=>['Delivered','Cancelled'].includes(o.status))" :key="o.id" :order="o"/></section></template>